solution:
public static int FindFirstTrue(bool[] flags)
{
    int lo = 0, hi = flags.Length;
    while (lo < hi)
    {
        int mid = lo + (hi - lo) / 2;
        if (flags[mid]) hi = mid;
        else lo = mid + 1;
    }
    return lo == flags.Length ? -1 : lo;
}

